-- ToneTurn: daily challenge leaderboard (spec I, async tournament).
-- The daily set is deterministic per day; its answer key is seeded from supabase/seed/daily_keys.sql
-- (generated by `npm run daily-keys`). The server grades the first play of each day and computes points
-- (spec J tournament points). The board shows today's player count, your rank, and your friends.
-- Run after 20261111000000_toneturn_rooms.sql, then run supabase/seed/daily_keys.sql. Safe to re-run.

create table if not exists public.toneturn_daily_keys (
  day date primary key,
  version int not null,
  answers text[] not null check (array_length(answers, 1) = 5)
);

create table if not exists public.toneturn_daily_results (
  user_id uuid not null references auth.users (id) on delete cascade,
  day date not null,
  version int not null,
  points int not null check (points between 0 and 7500),
  correct int not null check (correct between 0 and 5),
  squares text not null,
  answers text[] not null,
  times int[] not null,
  created_at timestamptz not null default now(),
  primary key (user_id, day)
);
create index if not exists toneturn_daily_results_day on public.toneturn_daily_results (day, points desc);

alter table public.toneturn_daily_keys enable row level security;
alter table public.toneturn_daily_results enable row level security;
revoke all on public.toneturn_daily_keys, public.toneturn_daily_results from anon, authenticated;

create or replace function public.toneturn_daily_board(p_day date)
returns jsonb language plpgsql stable security definer set search_path = '' as $$
declare
  me uuid := (select auth.uid());
  mine public.toneturn_daily_results;
  n int;
  rk int;
begin
  if me is null then raise exception 'sign in first'; end if;
  select count(*) into n from public.toneturn_daily_results r where r.day = p_day;
  select * into mine from public.toneturn_daily_results r where r.day = p_day and r.user_id = me;
  if mine.user_id is not null then
    select 1 + count(*) into rk from public.toneturn_daily_results r where r.day = p_day and r.points > mine.points;
  end if;
  return jsonb_build_object(
    'day', p_day,
    'players', n,
    'me', case when mine.user_id is null then null else jsonb_build_object(
      'points', mine.points, 'correct', mine.correct, 'squares', mine.squares, 'rank', rk,
      'top_percent', ceil(100.0 * rk / greatest(n, 1))::int) end,
    'friends', coalesce((
      select jsonb_agg(jsonb_build_object(
        'name', coalesce(nullif(p.display_name, ''), 'Player'), 'points', r.points, 'squares', r.squares, 'me', r.user_id = me
      ) order by r.points desc, r.created_at)
      from public.toneturn_daily_results r
      left join public.toneturn_profiles p on p.id = r.user_id
      where r.day = p_day and (r.user_id = me or exists (
        select 1 from public.toneturn_friendships f
        where f.status = 'accepted' and ((f.requester = me and f.addressee = r.user_id) or (f.addressee = me and f.requester = r.user_id))
      ))), '[]'::jsonb)
  );
end $$;

-- First play of a day counts; later submissions return the board unchanged.
create or replace function public.toneturn_daily_submit(p_day date, p_version int, p_answers text[], p_times int[])
returns jsonb language plpgsql security definer set search_path = '' as $$
declare
  me uuid := (select auth.uid());
  k public.toneturn_daily_keys;
  ok boolean;
  streak int := 0;
  pts int := 0;
  total int := 0;
  n_ok int := 0;
  sq text := '';
  f numeric;
begin
  if me is null then raise exception 'sign in first'; end if;
  -- Local calendar days run from UTC-12 to UTC+14.
  if p_day < (now() at time zone 'utc')::date - 1 or p_day > (now() at time zone 'utc')::date + 1 then raise exception 'not today'; end if;
  if exists (select 1 from public.toneturn_daily_results r where r.user_id = me and r.day = p_day) then
    return public.toneturn_daily_board(p_day);
  end if;
  select * into k from public.toneturn_daily_keys x where x.day = p_day;
  if k.day is null or k.version <> p_version then raise exception 'daily version mismatch'; end if;
  if coalesce(array_length(p_answers, 1), 0) <> 5 or coalesce(array_length(p_times, 1), 0) <> 5 then raise exception 'five answers expected'; end if;
  for i in 1..5 loop
    ok := p_answers[i] is not null and p_answers[i] = k.answers[i] and p_times[i] is not null and p_times[i] between 150 and 10000;
    if ok then
      f := greatest(0, least(1, 1 - p_times[i]::numeric / 10000));
      pts := round(1000 * (0.5 + 0.5 * f) * least(1.5, 1 + 0.1 * streak));
      total := total + pts;
      n_ok := n_ok + 1;
      streak := streak + 1;
      sq := sq || case when p_times[i] <= 2000 then '🟩' else '🟨' end;
    else
      streak := 0;
      sq := sq || '⬜';
    end if;
  end loop;
  insert into public.toneturn_daily_results (user_id, day, version, points, correct, squares, answers, times)
  values (me, p_day, p_version, total, n_ok, sq, (select array_agg(left(a, 32)) from unnest(p_answers) a), p_times);
  return public.toneturn_daily_board(p_day);
end $$;

revoke execute on function public.toneturn_daily_board(date) from public, anon;
revoke execute on function public.toneturn_daily_submit(date, int, text[], int[]) from public, anon;
grant execute on function public.toneturn_daily_board(date) to authenticated;
grant execute on function public.toneturn_daily_submit(date, int, text[], int[]) to authenticated;
